<?php

declare(strict_types=1);

namespace App\Domain\AnnualReport;

use App\Models\ClosingCheck;
use App\Models\FiscalYear;
use App\Support\Tenancy\CurrentCompany;
use Illuminate\Database\Eloquent\Builder;

/**
 * A person's answers on Bokslut → Regelverk for one fiscal year: yes or no
 * per question, and the revenue accounts the person has classified as
 * generated by buildings (K2 1.1B b). Read from `closing_checks` with one
 * query, or built from the form before it is saved, so the screen can show
 * what changes before anything is stored (spec Behaviour 1).
 */
final readonly class K3EligibilityAnswers
{
    /**
     * @param  array<string, bool>  $answers  question value => yes
     * @param  list<int>  $buildingAccounts  account numbers
     */
    public function __construct(
        public array $answers = [],
        public array $buildingAccounts = [],
        public bool $buildingClassified = false,
    ) {}

    public static function forYear(FiscalYear $fiscalYear): self
    {
        /** @var list<string> $keys */
        $keys = CurrentCompany::run($fiscalYear->company_id, fn (): array => self::query($fiscalYear)
            ->pluck('key')
            ->map(fn (mixed $key): string => (string) $key)
            ->values()
            ->all());

        return self::fromKeys($keys);
    }

    /**
     * The year's rows that hold these answers, inside the current company.
     *
     * @return Builder<ClosingCheck>
     */
    public static function query(FiscalYear $fiscalYear): Builder
    {
        return ClosingCheck::query()
            ->where('fiscal_year_id', $fiscalYear->id)
            ->where(fn (Builder $query) => $query->where('key', 'like', 'k2\_1\_1%')->orWhere('key', 'like', 'k3\_size\_%'));
    }

    /** @param list<string> $keys */
    public static function fromKeys(array $keys): self
    {
        $answers = [];
        $accounts = [];
        $classified = false;

        foreach ($keys as $key) {
            if ($key === K3EligibilityQuestion::BUILDING_CLASSIFIED) {
                $classified = true;

                continue;
            }

            if (str_starts_with($key, K3EligibilityQuestion::BUILDING_ACCOUNT_PREFIX)) {
                $accounts[] = (int) substr($key, strlen(K3EligibilityQuestion::BUILDING_ACCOUNT_PREFIX));

                continue;
            }

            $parsed = K3EligibilityQuestion::parse($key);

            if ($parsed !== null) {
                $answers[$parsed[0]->value] = $parsed[1];
            }
        }

        $accounts = array_values(array_unique($accounts));
        sort($accounts);

        return new self($answers, $accounts, $classified);
    }

    /**
     * The keys to store, one per answer and per classified account.
     *
     * @return list<string>
     */
    public function keys(): array
    {
        $keys = [];

        foreach ($this->answers as $question => $yes) {
            $keys[] = K3EligibilityQuestion::from($question)->key($yes);
        }

        if ($this->buildingClassified) {
            $keys[] = K3EligibilityQuestion::BUILDING_CLASSIFIED;

            foreach ($this->buildingAccounts as $number) {
                $keys[] = K3EligibilityQuestion::BUILDING_ACCOUNT_PREFIX.$number;
            }
        }

        sort($keys);

        return $keys;
    }

    public function answer(K3EligibilityQuestion $question): ?bool
    {
        return $this->answers[$question->value] ?? null;
    }
}
